  function oracle(arr) {
    const out = [];
    for (let i = 0; i < arr.length; i++) {
      if (i === 0 || arr[i] !== arr[i - 1]) out.push(arr[i]);
    }
    return out;
  }

  const vectors = [];
  const seen = new Set();
  function add(arr) {
    const key = arr.join(',');
    if (seen.has(key)) return;
    seen.add(key);
    const copy = [];
    for (let i = 0; i < arr.length; i++) copy[i] = arr[i];
    vectors.push([copy, oracle(arr)]);
  }

  add([]);
  for (let v = -10; v <= 10; v++) add([v]);
  add([1, 2, 3]);
  add([4, 4, 4, 4]);
  add([1, 1, 2, 3]);
  add([1, 2, 3, 3]);
  add([-3, -3, -1, 0, 0, 2]);
  add([1, 2, 2, 2, 3]);
  add([8, 8]);
  add([-1, 0]);
  add([0, 0, 0, 0]);

  for (let n = 1; n <= 40; n++) {
    for (const v of [-6, -3, -1, 0, 1, 2, 6, 7]) add(Array(n).fill(v));
  }
  for (let v = -6; v <= 6; v++) add(Array(19).fill(v));

  for (let v = -6; v <= 6; v++) {
    for (let w = v + 1; w <= 6; w++) {
      for (let split = 1; split < 19; split++) {
        add(Array(split).fill(v).concat(Array(19 - split).fill(w)));
      }
    }
  }

  for (let v = -6; v <= 4; v++) {
    const a = v, b = v + 1, c = v + 2;
    for (let i = 1; i <= 17; i++) {
      for (let j = 1; i + j <= 18; j++) {
        const k = 19 - i - j;
        if (k < 1) continue;
        add(Array(i).fill(a).concat(Array(j).fill(b), Array(k).fill(c)));
      }
    }
  }

  for (let rep = 1; rep <= 19; rep++) {
    for (let start = -6; start <= 6; start++) {
      const arr = [];
      let val = start;
      while (arr.length < 19 && val <= 6) {
        for (let r = 0; r < rep && arr.length < 19; r++) arr.push(val);
        val++;
      }
      if (arr.length === 19) add(arr);
    }
  }

  for (let dupAt = 0; dupAt < 18; dupAt++) {
    const base = [];
    for (let i = 0; i < 18; i++) base.push(i - 9);
    add(base.slice(0, dupAt + 1).concat([base[dupAt]], base.slice(dupAt + 1)));
  }

